import {workspaces,canRequest,demoRootUrl} from './model.js';
import {esc,icon,button,link,badge,notice,field,picker} from './ui.js';
export function createViews(s){
 const t=(en,zh)=>s.locale==='zh'?zh:en;
 const ws=(id=s.workspace)=>workspaces[id]??workspaces.org;
 const name=(id=s.workspace)=>id==='personal'?t('My journal','我的个人博客'):ws(id).name;
 const role=()=>s.workspace==='personal'?t('Personal owner','个人 Owner'):({admin:t('Organization admin','组织 Admin'),member:t('Organization member','组织 Member'),publisher:t('Publisher','发布者 Publisher')})[s.role];
 const kind=id=>ws(id).kind==='personal'?t('Personal','个人'):t('Organization','组织');
 const date=value=>value?new Intl.DateTimeFormat(s.locale==='zh'?'zh-CN':'en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):t('Not checked yet','尚未核验');
 const request=(id=s.workspace)=>s.requests[id];
 const statusInfo={queued:[t('Awaiting operations','待运维处理'),'amber'],working:[t('Setup in progress','开通中'),'purple'],info:[t('More information needed','待补充资料'),'amber'],verifying:[t('Checking the sites','核验中'),'blue'],partial:[t('Partially ready','部分开通'),'amber'],blocked:[t('Operations follow-up needed','待运维处理'),'red'],complete:[t('Both sites are ready','双语站点已就绪'),'green']};
 const status=r=>badge(...(statusInfo[r.status]??statusInfo.queued));
 const language=lang=>lang==='en'?t('English site','英文站点'):t('Chinese site','中文站点');
 const readyCount=r=>Object.values(r?.sites??{}).filter(x=>x.status==='ready').length;
 const localePicker=()=>picker('locale',t('Interface language','界面语言'),s.locale,[{value:'en',label:'English'},{value:'zh',label:'简体中文'}],'locale-picker');
 const pause=()=>`<div class="pause-note">${icon('pause')}<span>${t('Publishing stays paused. Completing setup will not publish an article.','发布执行保持暂停。开通完成不会自动发布文章。')}</span></div>`;
 function header(title,subtitle,actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
 function titleBlock(title,sub=''){return `<div class="panel-head"><h2>${esc(title)}</h2>${sub?`<span class="mono">${esc(sub)}</span>`:''}</div>`;}
 function fact(label,value){return `<div class="fact"><dt>${esc(label)}</dt><dd>${value}</dd></div>`;}
 function next(r){
  if(r.status==='queued')return t('Operations will review this request and prepare both language sites. You can keep writing.','运维将处理此申请并准备两个语言站点，期间可以继续写作。');
  if(r.status==='info')return canRequest(r.owner,s.role)?t('Please provide the requested information. We will continue with this same request.','请补充下方资料，运维会在同一申请中继续处理。'):t('Waiting for the workspace administrator to provide the requested information.','等待工作区管理员补充资料，随后由运维继续处理。');
  if(readyCount(r)===2&&r.rootCheck?.status!=='passed')return t('Both language sites passed. Operations still needs to verify that the root URL redirects to English.','两种语言站点已通过，运维还需核验根路径是否正确跳转英文。');
  if(r.status==='complete')return t('Your English and Chinese sites are ready. Publishing permissions and approvals still apply.','英文和中文站点已就绪，发文仍按当前权限与审批规则执行。');
  if(r.status==='partial')return t('One language site is ready. Operations will complete the other without rebuilding the existing site.','一个语言站点已就绪，运维会继续处理另一站点，已完成的站点保持不变。');
  if(r.status==='blocked')return t('A site check needs attention. Operations will resolve it in this request; no new application is needed.','站点核验遇到问题，运维会在本申请中继续处理，无需重新申请。');
  return t('Operations is configuring the sites. You will see the verified addresses here when each site is ready.','运维正在配置站点，核验通过后会在这里显示各语言的博客地址。');
 }
 function paperArt(){return `<div class="hero-art" aria-hidden="true"><div class="paper"><small>ZH</small><b>好内容，<br>有归处。</b><i></i><i></i><i></i></div><div class="paper"><small>EN</small><b>Ideas,<br>at home.</b><i></i><i></i><div class="paper-line"><i></i><span></span></div></div></div>`;}
 function steps(r){const active=r.status==='queued'?1:r.status==='info'||r.status==='working'?2:r.status==='complete'?4:3;return `<div class="milestones" aria-label="${t('Setup progress','开通进度')}">${[t('Requested','申请已提交'),t('Manual setup','运维开通'),t('Verification','逐站核验'),t('Ready','开通完成')].map((label,i)=>`<div class="milestone ${i<active-1||r.status==='complete'?'done':i===active-1?'current':''}"><i>${i<active-1||r.status==='complete'?icon('check'):i+1}</i><span>${label}</span></div>`).join('')}</div>`;}
 function progress(r,detail=false){return `<section class="panel status-card"><div class="status-title"><div>${status(r)}<h2>${esc(r.status==='complete'?t('A home for both languages.','两个语言站点，都已就绪。'):r.status==='info'?t('One detail before we continue.','补充一点信息，就能继续。'):r.status==='partial'?t('One site ready. One on the way.','一个已就绪，另一个正在路上。'):t('Your blog is taking shape.','博客正在准备中。'))}</h2><p>${esc(next(r))}</p></div><div class="status-orb">${icon(r.status==='complete'?'check':r.status==='info'?'mail':'clock')}</div></div>${steps(r)}<div class="status-foot"><small>${t('Updated','最近更新')} ${date(r.updatedAt)} · ${t('Handled by operations','由运维团队处理')}</small>${detail?link(t('Keep writing','继续写作'),'#draft','quiet','edit'):link(t('View request','查看开通进度'),'#request','soft','arrow')}</div></section>`;}
 function siteCard(owner,lang){const r=request(owner),site=r?.sites[lang],state=site?.status??'none',isReady=state==='ready';const labels={none:[t('Not set up','未开通'),'neutral'],pending:[t('Awaiting setup','待开通'),'neutral'],checking:[t('Awaiting verification','待核验'),'blue'],failed:[t('Needs attention','待处理'),'red'],ready:[t('Site ready','站点已就绪'),'green']};const copy={none:t('Your verified blog address will appear here.','开通并核验后，这里会显示博客地址。'),pending:t('Operations will prepare this language site.','运维将准备这个语言站点。'),checking:t('The address is registered. Site checks are still pending.','地址已登记，正在等待站点核验。'),failed:t('HTTPS verification needs attention. Operations is following up.','HTTPS 核验未通过，等待运维处理。'),ready:t('Address, connection and storage checks passed in this demo.','地址、连接及存储已通过演示核验。')};return `<section class="panel site-card ${state}"><div class="site-top"><div class="lang-icon">${lang.toUpperCase()}</div><h3>${lang==='en'?'English':'简体中文'}</h3>${badge(...labels[state])}</div><p>${t('Public blog address','公开博客地址')}</p><div class="url ${site?.url?'':'empty'}">${esc(site?.url||t('Assigned during setup','开通时分配'))}</div><p>${copy[state]}</p><div class="site-bottom"><small>${isReady?t('Checked','已核验')+' '+date(site.checkedAt):t('Independent Ghost site','独立 Ghost 站点')}</small>${isReady?link(t('View blog','访问博客'),`#blog?owner=${owner}&lang=${lang}`,'quiet','external'):button(t('View blog','访问博客'),'unavailable','quiet','external','disabled')}</div></section>`;}
 function rootStatus(r){const value=r?.rootCheck?.status;return badge(value==='passed'?t('Redirect verified','跳转已核验'):value==='failed'?t('Redirect needs attention','跳转待处理'):t('Redirect pending','跳转待核验'),value==='passed'?'green':value==='failed'?'red':'neutral');}
 function rootOverview(owner){const r=request(owner);return `<section class="panel root-overview"><div><div class="eyebrow">${t('ONE BLOG · TWO LANGUAGES','一个博客 · 两种语言')}</div><h3>${t('Blog entry','博客入口')}</h3><div class="url ${r?.rootUrl?'':'empty'}">${esc(r?.rootUrl||t('Platform subdomain assigned by operations','由运维分配平台子域名'))}</div></div><div class="root-rule"><strong>/ → /en/</strong><p>${t('Always opens English; independent of the CMS interface language.','默认进入英文，不随 CMS 界面语言改变。')}</p>${rootStatus(r)}${r?.rootCheck?.status==='passed'?link(t('Preview root entry','预览根入口'),`#blog?owner=${owner}&lang=en&entry=root`,'quiet','external'):''}</div></section>`;}
 function siteSection(owner){const r=request(owner);return `${rootOverview(owner)}<div class="section-label"><h2>${t('Language sites','语言站点')}</h2><p>${t('Ready','已就绪')} ${readyCount(r)} / 2</p></div><div class="site-grid">${['en','zh'].map(lang=>siteCard(owner,lang)).join('')}</div>`;}
 function howAside(){return `<section class="panel aside-card"><h3>${t('How setup works','博客如何开通')}</h3><p>${t('A little help getting started. Everything you need to publish, in one workspace.','开通由运维协助，日常创作与发布在工作区完成。')}</p><ol class="aside-steps"><li><span class="step-icon">${icon('file')}</span><div><strong>${t('Send a request','提交开通申请')}</strong><p>${t('Confirm the workspace and blog name.','确认所属工作区与博客名称。')}</p></div></li><li><span class="step-icon">${icon('server')}</span><div><strong>${t('Operations prepares the sites','运维准备站点')}</strong><p>${t('One domain, two Ghost sites at /en/ and /zh/.','一个域名，/en/ 与 /zh/ 分别对应两套 Ghost。')}</p></div></li><li><span class="step-icon">${icon('check')}</span><div><strong>${t('Verified, then ready','核验通过后开通')}</strong><p>${t('Check both paths and the root redirect to /en/.','核验两种语言路径及根路径跳转 /en/。')}</p></div></li></ol></section><div class="soft-aside">${icon('edit')}<h3>${t('Start with a draft','先写下第一个想法')}</h3><p>${t('You can write and submit for review while your sites are being prepared.','等待开通时，可以保存草稿和提交文章审核。')}</p>${link(t('Open the writing desk','进入写作工作台'),'#draft','quiet')}</div>`;}
 function summaryAside(r){return `<section class="panel aside-card"><h3>${t('Request details','申请信息')}</h3><dl class="facts">${fact(t('Workspace','所属工作区'),esc(name(r.owner))+'<br>'+badge(kind(r.owner)))}${fact(t('Blog name','博客名称'),esc(r.name))}${fact(t('Language sites','开通语言'),'English / 简体中文')}${fact(t('Site addresses','站点地址'),t('One platform subdomain · /en/ and /zh/','一个平台子域名 · /en/ 与 /zh/'))}${fact(t('Default entry','默认入口'),'/ → /en/ (English)')}${fact(t('Request ID','申请编号'),`<span class="mono">${esc(r.id)}</span>`)}${fact(t('Submitted','提交时间'),date(r.submittedAt))}</dl></section><div class="soft-aside">${icon('lock')}<h3>${t('Your workspace, your content','归属清楚，内容独立')}</h3><p>${t('These sites belong to this workspace. Personal and organization blogs remain separate.','两个站点都属于当前工作区，个人博客与组织博客独立管理。')}</p></div>`;}
 function sites(){const r=request();const allowed=canRequest(s.workspace,s.role);return `${header(t('Sites & workspace','站点与工作区'),t('A public home for your ideas, in two languages.','让内容，拥有自己的双语公开地址。'),button(t('Refresh status','刷新状态'),'refresh','','refresh'))}${s.readError?notice(t('Status is temporarily unavailable','暂时无法读取最新状态'),t('The last known information is kept below. Try again to check for updates.','下方保留上次已知信息，可重试读取最新状态。'),'warning',button(t('Try again','重新读取'),'recover','small')):''}<div class="layout"><div>${r?progress(r):`<section class="panel hero"><div><div class="eyebrow">${icon('globe')}${t('Operator-assisted setup','运维协助开通')}</div><h2>${t('Give your next idea a place of its own.','让下一个想法，拥有自己的博客。')}</h2><p>${t('Request a bilingual blog for','为')}${' '+esc(name())+' '}${t('and keep creating while we prepare the sites.','申请一个双语博客，站点准备期间也能继续创作。')}</p><div class="button-row">${allowed?button(t('Request blog setup','申请开通博客'),'apply','primary','plus'):button(t('An administrator needs to apply','需由组织管理员申请'),'admin-info','soft','users')}${link(t('Start writing','先写一篇草稿'),'#draft','quiet','edit')}</div></div>${paperArt()}</section>`}${siteSection(s.workspace)}${pause()}${r?.status==='info'?`<div style="margin-top:20px">${notice(t('Information needed','需要补充资料'),r.infoReason,'warning',allowed?button(t('Provide information','补充资料'),'supplement','small'):button(t('View request','查看申请'),'request','small'))}</div>`:''}<p class="demo-warning">${icon('info')}${t('Preview data only. No sites are deployed and no content is sent.','此处为交互演示数据，不会部署站点或发送文章。')}</p></div><aside class="stack">${howAside()}</aside></div>`;}
 const eventTitle=(e)=>({submitted:t('Setup request submitted','已提交开通申请'),claimed:t('Operations started processing','运维已开始处理'),info:t('Additional information requested','运维请求补充资料'),supplement:t('Additional information provided','申请人已补充资料'),registered:language(e.language)+' · '+t('address registered','地址已登记'),verified:language(e.language)+' · '+t('checks passed','核验通过'),failed:language(e.language)+' · '+t('verification needs attention','核验未通过'),'root-registered':t('Blog root registered; language paths generated','博客根地址已登记，语言路径已生成'),'root-changed':t('Blog root changed; all checks must run again','博客根地址已修改，全部检查需重新核验'),'root-verified':t('Root redirect to English passed','根路径跳转英文核验通过'),'root-failed':t('Root redirect needs attention','根路径跳转核验未通过'),'legacy-complete':t('Language sites passed under the old addresses; root redirect was not checked','旧地址的双语站点曾通过；当时未核验根入口'),'address-layout':t('Address layout updated; old verification is invalid','地址结构已调整，旧核验结果已失效'),complete:t('Both language sites and the root entry are ready','双语站点与根入口已就绪')})[e.type];
 function timeline(r){return `<section class="panel">${titleBlock(t('Activity','处理记录'))}<div class="panel-body"><ol class="timeline">${[...r.events].reverse().map(e=>`<li><h3>${esc(eventTitle(e))}</h3><time>${date(e.at)}</time>${e.note?`<p>${esc(e.note)}</p>`:''}${e.type==='failed'?`<p>${t('HTTPS verification did not pass. Operations will resolve it in the same request.','HTTPS 核验未通过，运维将在同一申请中继续处理。')}</p>`:''}${e.type==='address-layout'?`<p>${t('The request and drafts were kept. Operations must recheck /en/, /zh/ and the root redirect.','申请与草稿已保留。运维需重新核验 /en/、/zh/ 及根路径跳转。')}</p>`:''}${e.type==='complete'?`<p>${t('Setup is complete. Publishing remains paused.','站点开通完成，发布执行仍保持暂停。')}</p>`:''}</li>`).join('')}</ol></div></section>`;}
 function requestPage(){const r=request();if(!r)return `${header(t('Setup request','开通申请'),t('Apply once. Follow every step here.','提交一次申请，在这里查看每一步。'))}<section class="panel empty-state"><div class="status-orb">${icon('file')}</div><h2>${t('No setup request yet','当前还没有开通申请')}</h2><p>${t('Request both language sites for this workspace. You can continue writing while operations prepares them.','为当前工作区申请中英文站点，等待期间可以继续创作。')}</p>${canRequest(s.workspace,s.role)?button(t('Request blog setup','申请开通博客'),'apply','primary','plus'):button(t('Ask the organization administrator','查看申请权限说明'),'admin-info','soft')}</section>`;return `${link(t('Back to sites','返回站点总览'),'#sites','quiet','back')}${header(t('Your blog setup','博客开通进度'),`${r.name} · ${r.id}`,link(t('Keep writing','继续写作'),'#draft','','edit'))}<div class="layout"><div class="stack">${progress(r,true)}${r.status==='info'?notice(t('Operations needs additional information','运维需要补充资料'),r.infoReason,'warning',canRequest(s.workspace,s.role)?button(t('Provide information','补充资料'),'supplement','small'):`<p>${t('An organization administrator can respond to this request.','组织管理员可以在此补充资料。')}</p>`):''}<div>${siteSection(s.workspace)}${pause()}</div>${timeline(r)}</div><aside class="stack">${summaryAside(r)}</aside></div>`;}
 function queue(){const rows=Object.values(s.requests).filter(Boolean);const filters=[['all',t('All requests','全部申请')],['queued',t('Unassigned','待处理')],['working',t('In progress','处理中')],['info',t('Needs information','待补充')],['complete',t('Completed','已完成')]];const matches=(r,f)=>f==='all'||f==='working'&&['working','verifying','partial','blocked'].includes(r.status)||r.status===f;const shown=rows.filter(r=>matches(r,s.queueFilter)&&`${r.name} ${r.id} ${name(r.owner)}`.toLowerCase().includes(s.queueSearch.toLowerCase()));return `${header(t('Blog setup requests','博客开通申请'),t('A clear handoff from request to verified language sites.','从申请到双语核验，让每一次开通都有明确进度。'),badge(t('Manual provisioning','人工部署'),'purple','server'))}<div class="queue-summary">${filters.map(([key,label])=>`<button type="button" data-action="filter" data-filter="${key}" class="${s.queueFilter===key?'active':''}">${label}<b>${rows.filter(r=>matches(r,key)).length}</b></button>`).join('')}</div><div class="queue-toolbar"><label class="search-wrap">${icon('search')}<input id="queue-search" class="search-input" value="${esc(s.queueSearch)}" placeholder="${t('Search workspace or request ID','搜索工作区或申请编号')}" aria-label="${t('Search requests','搜索开通申请')}"></label><p>${t('Requests are handled by operations. No automatic deployments.','申请由运维处理，不会自动创建部署任务。')}</p></div><section class="panel"><table class="queue-table"><thead><tr><th>${t('Workspace / request','工作区 / 申请')}</th><th>${t('Status','状态')}</th><th>${t('Language sites','语言站点')}</th><th>${t('Next step','下一步')}</th></tr></thead><tbody>${shown.map(r=>`<tr><td><div class="queue-name"><div class="avatar">${ws(r.owner).initials}</div><div><a href="#ops/detail?owner=${r.owner}"><strong>${esc(name(r.owner))}</strong></a><small>${r.id}</small></div></div></td><td>${status(r)}<p>${r.assignee?t('Assigned to operations','运维处理中'):t('Unassigned','待领取')}</p></td><td><strong>${readyCount(r)} / 2 ${t('ready','已就绪')}</strong><p>English / 简体中文</p></td><td><p>${r.status==='info'?t('Waiting for applicant','等待申请人补充'):r.status==='complete'?t('Setup complete','开通完成'):r.assignee?t('Continue verification','继续处理与核验'):t('Claim this request','领取申请')}</p>${link(t('View request','查看申请'),`#ops/detail?owner=${r.owner}`,'quiet','arrow')}</td></tr>`).join('')}</tbody></table>${shown.length?'':`<div class="empty-state"><h3>${t('No matching requests','没有符合条件的申请')}</h3><p>${t('Try another filter or search term.','试试其他筛选条件或搜索内容。')}</p></div>`}<div class="queue-foot"><span>${shown.length} ${t('requests','项申请')}</span><span>${t('Local prototype data','本地原型数据')}</span></div></section>${pause()}`;}
 const checks={ownership:[t('Workspace & language','工作区与语言'),t('Matches this request and the selected language.','确认绑定当前申请及所选语言。')],https:[t('Public address & HTTPS','公开地址与 HTTPS'),t('The public entry is reachable with a valid certificate.','公开入口可访问，证书与地址匹配。')],routing:[t('Language path & assets','语言路径与资源'),t('The correct Ghost handles this path; article links and assets keep the language prefix.','路径对应正确 Ghost，文章与资源链接保留语言前缀。')],connection:[t('Ghost connection & author mapping','Ghost 连接与作者映射'),t('The connection and configured byline mapping are available.','连接及已配置署名映射可用。')],storage:[t('Private and public media storage','私有与公开媒体存储'),t('Storage configuration is in place; no article is published.','核对存储配置，不执行文章发布。')]};
 function operatorRootPanel(r,dirty){const owner=r.owner,draft=s.operatorRoots[owner]??(r.rootUrl||demoRootUrl(owner));return `<section class="panel">${titleBlock(t('Shared blog address','统一博客地址'),'/en/ · /zh/')}<div class="panel-body"><p class="text-note">${t('Allocate one platform subdomain, deploy two Ghost instances, then register the root once.','分配一个平台子域名，部署两套 Ghost，只需登记一次根地址。')}</p><div class="input-with-button">${field(t('Blog root URL','博客根地址'),'blog-root',draft)}${button(r.rootUrl?t('Update root','更新根地址'):t('Register root','登记根地址'),'register-root','','',!r.assignee||r.status==='info'?'disabled':'')}</div><p class="field-hint">${t('Demo example: https://richard.chronoai.example/ — no language path. The actual platform base domain is deployment configuration.','演示示例：https://richard.chronoai.example/，不填写语言路径。实际平台根域名由部署配置决定。')}</p><div class="path-map"><div><b>/en/</b><span>English · Ghost</span></div><div><b>/zh/</b><span>简体中文 · Ghost</span></div><div><b>/ → /en/</b><span>${t('Default English entry','默认英文入口')}</span></div></div><div class="root-check"><div><strong>${t('Root redirect to English','根路径跳转英文')}</strong><p>${t('Check the redirect and the English destination separately from the two language checks.','独立核验根路径跳转及英文目标，不能用语言站点通过代替此检查。')}</p>${rootStatus(r)}</div>${button(r.rootCheck.status==='passed'?t('Redirect verified','根入口已核验'):t('Verify root redirect','核验根入口'),'verify-root','soft','check',!r.assignee||r.status==='info'||r.sites.en.status!=='ready'||r.rootCheck.status==='passed'||dirty?'disabled':'')}</div>${r.sites.en.status!=='ready'?`<p class="field-hint">${t('Verify English first. The root always targets /en/, even when Chinese is ready.','先核验英文站点。即使中文已就绪，根路径仍固定指向 /en/。')}</p>`:''}${dirty&&r.rootUrl?`<p class="field-hint" id="root-dirty">${t('Updating the root will invalidate both language checks and the redirect check.','修改根地址会使两语言及根入口的旧核验结果失效。')}</p>`:''}<p class="text-note">${t('Simulated checks only. Real verification will use a CMS backend API; it has not been implemented here.','此处仅模拟核验，真实核验需由 CMS 后端 API 执行，本轮未实现。')}</p><a class="text-link" href="review.html#operations">${t('Read the operations flow','查看运维流程说明')} →</a></div></section>`;}
 function operatorDetail(owner){const r=request(owner);if(!r)return `${header(t('No request to process','当前没有待处理申请'),t('A workspace administrator needs to submit a setup request first.','工作区管理员提交开通申请后，才会进入运维处理流程。'),link(t('All requests','查看全部申请'),'#ops'))}<section class="panel empty-state">${button(t('Return to workspace view','返回工作区视角'),'user-view','primary')}</section>`;const lang=s.activeLanguage,site=r.sites[lang],addressDirty=s.operatorRoots[owner]!==undefined&&s.operatorRoots[owner]!==r.rootUrl;return `<a class="back-link" href="#ops">${icon('back')}${t('All setup requests','返回开通申请列表')}</a>${header(r.name,t('Manual setup and verification','人工开通与核验')+' · '+r.id,status(r))}<div class="layout"><div class="stack"><section class="panel">${titleBlock(t('Request information','开通资料'),kind(owner))}<div class="panel-body"><dl class="facts facts-grid">${fact(t('Workspace','所属工作区'),esc(name(owner)))}${fact(t('Public blog name','博客公开名称'),esc(r.name))}${fact(t('Site addresses','站点地址'),t('One platform subdomain · /en/ and /zh/','一个平台子域名 · /en/ 与 /zh/'))}${fact(t('Requested languages','申请语言'),'English / 简体中文')}</dl>${r.note?`<p class="text-note">${t('Applicant note','申请备注')}：${esc(r.note)}</p>`:''}${r.supplement?`<div style="margin-top:20px">${notice(t('Applicant response','申请人已补充'),r.supplement,'info')}</div>`:''}</div></section>${operatorRootPanel(r,addressDirty)}<section class="panel">${titleBlock(t('Language site verification','语言站点核验'),`${readyCount(r)} / 2`)}<div class="panel-body"><div class="tabs">${['en','zh'].map(l=>button(l==='en'?'English':'简体中文','op-language',`tab ${lang===l?'active':''}`,r.sites[l].status==='ready'?'check':'',`data-lang="${l}" aria-pressed="${lang===l}"`)).join('')}</div><div class="derived-address"><small>${t('Generated from the shared blog root','由同一博客根地址生成')}</small><div class="url">${esc(site.url||t('Register the blog root first','请先登记博客根地址'))}</div></div><div class="operator-checks">${Object.entries(checks).map(([key,[title,copy]])=>{const result=site.checks.find(x=>x.key===key);return `<div class="check-row"><span class="check-symbol ${result?(result.ok?'pass':'fail'):''}">${icon(result?(result.ok?'check':'close'):'clock')}</span><div><strong>${title}</strong><p>${copy}</p></div>${badge(result?(result.ok?t('Passed','通过'):t('Failed','未通过')):t('Pending','待核验'),result?(result.ok?'green':'red'):'neutral')}</div>`;}).join('')}${site.status==='failed'?notice(t('HTTPS check did not pass','HTTPS 核验未通过'),t('Resolve the certificate configuration, then check this same site again. The other language site will be preserved.','修复证书配置后，重新核验同一站点。另一语言站点不会受到影响。'),'error'):''}${site.status==='ready'?notice(t('This language site is ready','当前语言站点已就绪'),t('Checked','核验时间')+' '+date(site.checkedAt)+'. '+t('No article was published.','未执行文章发布。'),'success'):''}${r.status==='info'?notice(t('Waiting for the applicant','等待申请人补充'),r.infoReason,'warning'):''}<div class="button-row">${button(site.status==='ready'?t('Verification passed','核验已通过'):site.status==='failed'?t('Check this site again','重新核验当前站点'):t('Verify this site','核验当前站点'),'verify-site','primary','check',!r.assignee||!site.url||site.status==='ready'||r.status==='info'||addressDirty?'disabled':'')}${site.url?link(t('Inspect site preview','查看站点样例'),`#blog?owner=${owner}&lang=${lang}`,'quiet','external'):''}</div>${addressDirty?`<p class="field-hint" id="address-dirty">${t('The root address has unsaved changes. Register or restore it before verification.','根地址有未登记修改，请先登记或恢复原地址，再执行核验。')}</p>`:''}${!r.assignee?`<p class="field-hint">${t('Claim the request before registering and verifying sites.','先领取申请，再登记和核验站点。')}</p>`:!site.url?`<p class="field-hint">${t('Register the shared blog root first. Both language paths are generated automatically.','先登记博客根地址，系统自动生成两种语言路径。')}</p>`:''}<p class="text-note">${t('This prototype simulates checks. It does not connect to Ghost, create resources, or publish content.','这里模拟核验结果，不连接 Ghost、不创建资源、不发布内容。')}</p></div></div></section>${timeline(r)}</div><aside class="stack"><section class="panel claim-card"><div class="avatar lavender">OP</div><h3>${r.assignee?t('Assigned to operations','运维正在处理'):t('Ready for a handoff','等待运维接单')}</h3><p>${r.status==='info'?t('This request is assigned. Wait for the applicant’s response before continuing setup.','申请已领取，等待申请人补充资料后再继续开通。'):r.assignee?t('Continue this request through setup and verification. Each language is handled independently.','在同一申请中完成开通与核验，两种语言独立处理。'):t('Claim this request, then manually prepare its Ghost sites and register the results here.','领取后手动准备 Ghost 站点，在这里登记结果与进度。')}</p>${!r.assignee?button(t('Claim request','领取并开始处理'),'claim','primary full','check'):badge(t('Operations team','运维团队'),'purple','users')}${r.status!=='complete'?button(t('Request information','请求补充资料'),'ask-info','full','mail'):''}</section><section class="panel aside-card"><h3>${t('Public progress','用户侧进度')}</h3><p>${t('Updates on this request appear in the workspace’s setup details. Internal notes stay in operations.','处理进度会展示在工作区的申请详情中，内部备注仅在运维视角可见。')}</p>${button(t('View as the applicant','查看用户侧效果'),'as-applicant','full','external',['org','personal'].includes(owner)?'':'disabled')}</section><section class="panel aside-card">${field(t('Internal note','运维内部备注'),'internal-note',r.internalNote,{area:true,placeholder:t('Only visible in the operator view','仅在运维视角展示'),max:1000})}<p class="field-hint">${t('Saved locally as you type.','输入时自动保存在本机演示数据中。')}</p></section>${pause()}</aside></div>`;}
 function draft(){const d=s.drafts[s.workspace],r=request();return `${header(t('Your writing desk','写作工作台'),t('Keep creating while your blog is being prepared.','开通等待期间，也能继续写作。'),link(t('View site setup','查看站点进度'),r?'#request':'#sites','','globe'))}${notice(t('Private draft · prototype','私有草稿 · 原型演示'),t('This draft is saved only in this browser. It is not submitted to the real CMS.','内容仅保存在当前浏览器，不会提交到真实 CMS。'),'neutral')}<section class="panel draft-editor" style="margin-top:22px">${field(t('Article title','文章标题'),'draft-title',d.title,{placeholder:t('A title for your next idea','为下一个想法写个标题'),max:200})}${field(t('Article text','文章正文'),'draft-body',d.body,{area:true,placeholder:t('Start writing…','从这里开始写作…'),max:10000})}<p class="field-hint">${icon('check')} ${t('Saved on this device as you type','输入时自动保存在本机')}</p></section>${pause()}`;}
 function blog(owner,lang,rootEntry=false){const r=request(owner);return `<div class="reader"><header class="reader-header"><strong>${esc(r?.name??name(owner))}</strong><nav class="reader-languages" aria-label="${t('Blog language','博客语言')}">${['en','zh'].map(value=>r?.sites[value]?.status==='ready'?link(value==='en'?'English':'简体中文',`#blog?owner=${owner}&lang=${value}`,value===lang?'soft':'quiet'):button(value==='en'?'English':'简体中文','unavailable','quiet','','disabled')).join('')}</nav></header>${rootEntry?notice(t('Root entry preview → English','根入口预览 → 英文'),`${r?.rootUrl??''} → ${r?.sites.en.url??''} · `+t('This local preview simulates the redirect; no server redirect was changed.','此处模拟跳转效果，未修改真实服务器重定向。'),'neutral'):''}<div class="reader-intro"><div class="eyebrow">${t('Public blog preview','公开博客效果预览')}</div><h1>${lang==='en'?'A place for ideas worth sharing.':'让值得分享的想法，<br>在这里相遇。'}</h1><p>${lang==='en'?'Notes, perspectives, and stories from '+esc(name(owner))+'.':esc(name(owner))+' 的思考、观点与故事。'}</p><div class="mono">${esc(r?.sites[lang]?.url??'—')}</div></div><section class="reader-empty"><h2>${lang==='en'?'Your first story starts here.':'第一篇故事，从这里开始。'}</h2><p>${t('No articles have been published by this prototype. This page shows the blog destination only.','本原型没有发布任何文章，此页仅演示开通后的博客入口。')}</p>${button(t('Return to setup','返回站点流程'),'back-from-blog','soft','back')}</section>${notice(t('Local preview','本地效果预览'),t('This is an example page, not a live Ghost site. The .example address is not opened.','这是本地样例页面，并非真实 Ghost 站点，也不会打开 .example 域名。'),'neutral')}</div>`;}
 function tools(route){const options=[['custom',t('Current progress','当前进度')],['new',t('First-time setup','首次申请')],['queued',t('Awaiting operations','待运维处理')],['info',t('Needs information','待补充资料')],['working',t('Setup in progress','运维处理中')],['partial',t('One site needs attention','部分开通 / 失败')],['complete',t('Both sites ready','双语开通完成')],['unavailable',t('Status unavailable','状态暂不可读')]].map(([value,label])=>({value,label}));const ops=route.startsWith('ops');return `<div class="prototype-tools" aria-label="${t('Prototype controls','原型演示控制')} "><span class="prototype-label"><i></i><span>${t('Prototype · local data','交互原型 · 本机数据')}</span></span><span class="tool-divider"></span>${picker('scenario',t('Demo scenario','演示场景'),s.scenario,options)}${!ops&&s.workspace==='org'?picker('role',t('Demo identity','演示身份'),s.role,[{value:'admin',label:'Admin'},{value:'member',label:'Member'},{value:'publisher',label:'Publisher'}]):''}${ops?picker('result',t('Demo verification result','演示核验结果'),s.checkResult,[{value:'pass',label:t('Check: pass','核验：通过')},{value:'fail',label:t('Check: fail','核验：失败')}],'result-picker'):''}${button(ops?t('User view','用户视角'):t('Operations view','运维视角'),ops?'user-view':'ops-view','quiet',ops?'users':'server')}<span class="tool-divider"></span><button type="button" class="icon-button" data-action="reset" aria-label="${t('Reset prototype data','重置原型数据')}" title="${t('Reset prototype data','重置原型数据')}">${icon('refresh')}</button></div>`;}
 function sidebar(route){const ops=route.startsWith('ops');const links=ops?[['#ops',t('Setup requests','开通申请'),'file',true]]:[['#draft',t('Writing desk','写作工作台'),'edit',route==='draft'],['#sites',t('Sites & workspace','站点与工作区'),'globe',route==='sites'],['#request',t('Setup request','开通申请'),'file',route==='request']];return `<aside class="sidebar"><a class="wordmark" href="${ops?'#ops':'#sites'}"><span class="brand-symbol">◈</span><span>ChronoAI<small>${ops?'OPERATIONS':'PUBLISHING STUDIO'}</small></span></a><div class="workspace-card"><span class="avatar">${ops?'OP':ws().initials}</span><div>${ops?`<small>${t('Operator view','运维视角')}</small><strong style="display:block;font-size:13px">${t('Platform operations','平台运维')}</strong>`:`<small>${t('Workspace','工作区')}</small>${picker('workspace',t('Choose workspace','选择工作区'),s.workspace,[{value:'org',label:'ChronoAI',detail:t('Organization workspace','组织工作区')},{value:'personal',label:t('My journal','我的个人博客'),detail:t('Personal workspace','个人工作区')}])}`}</div></div><div class="nav-label">${ops?t('OPERATIONS','运维工作台'):t('WORKSPACE','工作区')}</div><nav class="nav">${links.map(([href,label,ico,active])=>`<a class="nav-item ${active?'active':''}" href="${href}" ${active?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}<button type="button" class="nav-item" data-action="help">${icon('info')}${t('How it works','使用说明')}</button></nav>${ops?`<p class="nav-note">${t('Manual provisioning.<br>Clear, verifiable handoffs.','人工部署，<br>每一步都有迹可循。')}</p>`:''}<div class="sidebar-foot"><div class="session-note">${icon('lock')}${t('Local interaction prototype','本地交互原型')}</div><div class="profile"><span class="avatar lavender">${ops?'OP':'CH'}</span><div><strong>${ops?t('Operations','运维人员'):s.workspace==='personal'?t('Personal workspace','个人工作区'):'ChronoAI'}</strong><small>${ops?t('Demo identity','演示身份'):role()}</small></div></div></div></aside>`;}
 function shell(route,params){const ops=route.startsWith('ops');const page=route==='sites'?sites():route==='request'?requestPage():route==='ops'?queue():route==='ops/detail'?operatorDetail(params.get('owner')??s.workspace):route==='draft'?draft():route==='blog'?blog(params.get('owner')??s.workspace,params.get('lang')==='zh'?'zh':'en',params.get('entry')==='root'):sites();const pageNames={sites:t('Sites & workspace','站点与工作区'),request:t('Setup progress','开通进度'),ops:t('Setup requests','开通申请'),'ops/detail':t('Process request','处理申请'),draft:t('Writing desk','写作工作台'),blog:t('Blog preview','博客预览')};return `<div class="shell">${sidebar(route)}<div class="app-body"><header class="topbar"><div class="breadcrumb"><span>${ops?t('Platform operations','平台运维'):esc(name())}</span>${icon('arrow')}<strong>${pageNames[route]??pageNames.sites}</strong></div><div class="top-actions">${badge(t('Publishing paused','发布执行暂停'),'neutral','pause')}${localePicker()}</div></header><main class="main" id="main" tabindex="-1">${s.readError&&route!=='sites'?notice(t('Status is temporarily unavailable','暂时无法读取最新状态'),t('The last known information is shown below. Try again to check for updates.','下方保留上次已知信息，可重试读取最新状态。'),'warning',button(t('Try again','重新读取'),'recover','small')):''}${page}</main></div></div>${tools(route)}`;}
 function dialog(type,owner=s.workspace){const r=request(owner);let title='',body='',footer='';const cancel=button(t('Close','关闭'),'close-dialog','quiet');
  if(type==='apply'){const f=s.forms[owner];title=t('Request blog setup','申请开通博客');body=`<p class="dialog-intro">${t('Tell us what to call your blog. Operations will take care of the setup.','确认博客名称，剩下的开通工作交给运维。')}</p><div class="scope-card"><span class="avatar">${ws(owner).initials}</span><div><strong>${esc(name(owner))} ${badge(kind(owner))}</strong><p>${t('This application belongs to this workspace.','本次申请及开通站点均归属于此工作区。')}</p></div></div>${field(t('Blog name','博客名称'),'apply-name',f.name,{required:true,max:80,placeholder:t('e.g. ChronoAI Journal','例如：ChronoAI Journal')})}<div class="form-label">${t('Language sites','开通语言')}</div><div class="language-chips"><span class="language-chip">${icon('check')}English</span><span class="language-chip">${icon('check')}简体中文</span></div><p class="language-help">${t('Two independent Ghost instances behind one blog domain. Articles are not translated automatically.','同一博客域名下仍是两套独立 Ghost，不会自动翻译文章内容。')}</p>${notice(t('One domain, two language paths','同一域名，两种语言路径'),t('Operations assigns one platform subdomain. English uses /en/, Chinese uses /zh/, and the root URL always redirects to /en/.','运维分配一个平台子域名：英文使用 /en/，中文使用 /zh/，根路径默认跳转 /en/。'),'neutral')}${field(t('Anything operations should know?','给运维的备注'),'apply-note',f.note,{optional:t('Optional','选填'),area:true,placeholder:t('Anything else about your blog setup…','例如需要运维了解的开通说明…')})}<p class="form-error" id="form-error" role="alert"></p>`;footer=`<small>${t('Draft saved on this device','申请草稿自动保存在本机')}</small><div class="button-row">${button(t('Save & close','暂存并关闭'),'close-dialog','quiet')}${button(t('Submit request','提交开通申请'),'submit-request','primary')}</div>`;}
  if(type==='supplement'){title=t('Provide information','补充开通资料');body=`<p class="dialog-intro">${esc(r.name)} · ${esc(r.id)}</p><div style="margin:20px 0">${notice(t('Operations needs a detail','运维需要补充的信息'),r.infoReason,'warning')}</div>${field(t('Your response','补充说明'),'supplement-text',s.supplementDrafts?.[owner]??r.supplement,{area:true,required:true,placeholder:t('Add the requested details here…','在这里填写所需资料…')})}<p class="field-hint">${t('We will continue with this same request. Existing sites will be preserved.','将在同一申请中继续处理，保留已完成的站点。')}</p><p class="form-error" id="form-error" role="alert"></p>`;footer=`${cancel}${button(t('Send information','提交补充资料'),'send-supplement','primary')}`;}
  if(type==='ask-info'){title=t('Request additional information','请求补充资料');body=`<p class="dialog-intro">${t('The workspace owner or organization administrator will see this message.','此说明将展示给个人 Owner 或组织管理员。')}</p><div class="scope-card"><span class="avatar">${ws(owner).initials}</span><div><strong>${esc(r.name)}</strong><p>${esc(r.id)}</p></div></div>${field(t('What is needed?','需要补充什么？'),'info-reason',s.infoDrafts?.[owner]??'',{area:true,required:true,placeholder:t('e.g. Please confirm the public blog name.','例如：请确认博客的公开名称。'),hint:t('Describe exactly what is missing. Do not ask for passwords or credentials.','说明具体缺项，不要求提供密码或密钥。'),max:600})}<p class="form-error" id="form-error" role="alert"></p>`;footer=`${cancel}${button(t('Request information','发送补充请求'),'send-info','primary')}`;}
  if(type==='admin-info'){title=t('An administrator can request setup','由组织管理员申请开通');body=`<p class="dialog-intro">${t('Members and Publishers can follow setup progress. An organization Admin needs to submit the request and provide any additional information.','组织 Member 和 Publisher 可以查看开通进度，由组织 Admin 提交申请并补充资料。')}</p><div style="margin-top:22px">${notice(t('Writing can continue','可以继续写作'),t('Save your drafts or submit articles for review while the site is being prepared.','站点准备期间可以保存草稿和提交文章审核。'),'neutral')}</div>`;footer=cancel;}
  if(type==='change-root'){const r=request(owner);title=t('Update the shared blog address?','更新统一博客地址？');body=`<p class="dialog-intro">${t('Both language addresses will change. Existing language and root verification results will be cleared; the request, notes and writing drafts stay.','两种语言地址将一起改变，原有语言站点与根入口核验结果会清空；申请、备注和写作草稿保留。')}</p><dl class="facts">${fact(t('Current root','当前根地址'),esc(r.rootUrl))}${fact(t('New root','新根地址'),esc(s.operatorRoots[owner]))}${fact(t('Default entry','默认入口'),'/ → /en/')}</dl>`;footer=`${cancel}${button(t('Update and recheck','更新并重新核验'),'confirm-root','primary')}`;}
  if(type==='help'){title=t('A clear path to your blog','从申请到自己的博客');body=`<p class="dialog-intro">${t('Apply in the workspace, then switch to Operations. Register one blog root and verify /en/, /zh/ and the root redirect to English.','先申请开通，再切换「运维视角」登记一个博客根地址，分别核验 /en/、/zh/ 和根路径跳转英文。')}</p><div style="margin-top:20px">${notice(t('Try the important states','体验关键状态'),t('The bottom scenario picker includes missing information, partial success, and completion. Verification results can be simulated in Operations.','底部场景选择器可体验待补充、部分开通和完成状态，运维视角可切换模拟核验结果。'),'info')}</div><p class="text-note">${t('All data is stored in this browser. No API, resource provisioning, credentials or publishing is involved. The public addresses are .example placeholders.','数据仅存于当前浏览器，不调用 API、不创建资源、不使用凭证、不执行发布。公开地址使用 .example 占位域名。')}</p>`;footer=cancel;}
  if(type==='reset'){title=t('Reset the prototype?','重置本机演示数据？');body=`<p class="dialog-intro">${t('This resets only this prototype’s requests and writing samples. The real CMS and Ghost data are not connected.','只会重置本原型的申请和写作样例，原型没有连接真实 CMS 或 Ghost 数据。')}</p>`;footer=`${cancel}${button(t('Reset demo data','重置演示数据'),'confirm-reset','primary')}`;}
  return `<div class="dialog-header"><h2 id="dialog-title">${title}</h2>${localePicker()}<button type="button" class="icon-button" data-action="close-dialog" aria-label="${t('Close dialog','关闭弹窗')}">${icon('close')}</button></div><div class="dialog-content">${body}</div><div class="dialog-footer">${footer}</div>`;
 }
 return {t,shell,dialog,date,name,statusInfo};
}
